INSERT INTO morphus_characteristics
  (key, table_name, roll_low, roll_high, name, kind, routes, route_rule, bonuses, horror_factor, horror_factor_set, sub_choices, description, note, source, source_book, system)
VALUES
  ('Appearance: Appearance Table', 'Appearance', 0, 0, 'Appearance Table', 'intro', NULL, NULL, NULL, NULL, NULL, NULL, 'Roll or select one. Mandatory entry point for building a Nightbane''s Morphus (True Shape); every result routes to one or more further tables.', NULL, 'import', 'Nightbane RPG p.92', 'nightbane'),
  ('Appearance: Almost human', 'Appearance', 1, 20, 'Almost human', 'route', '[{"table": "Nightbane Characteristics", "count": 1}]', 'If the result asks for more than one characteristic, ignore it and reroll (only a single characteristic is allowed from this entry).', NULL, NULL, NULL, NULL, 'The Nightbane''s Morphus is almost totally human, except for one inhuman trait that might be disguised or concealed - although sometimes the trait is inhuman enough to give away the character''s true supernatural nature.', NULL, 'import', 'Nightbane RPG p.92', 'nightbane'),
  ('Appearance: Inhuman but beautiful', 'Appearance', 21, 30, 'Inhuman but beautiful', 'route', '[{"table": "Unearthly Beauty", "count": 1}, {"table": "Nightbane Characteristics", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'The Nightbane combined a beautiful appearance with rolls on the Unearthly Beauty Table and the Nightbane Characteristics Table.', NULL, 'import', 'Nightbane RPG p.92', 'nightbane'),
  ('Appearance: Marred Beauty', 'Appearance', 31, 45, 'Marred Beauty', 'route', '[{"table": "Unearthly Beauty", "count": 1}, {"table": "Stigmata", "count": 1}, {"table": "Nightbane Characteristics", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'The character has a beautiful True Shape, but it is marred by a gruesome stigmata.', NULL, 'import', 'Nightbane RPG p.92', 'nightbane'),
  ('Appearance: Lycanthrope', 'Appearance', 46, 60, 'Lycanthrope', 'route', '[{"table": "Animal Form", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'The Nightbane''s Morphus is a mixture of animal and humanoid traits.', NULL, 'import', 'Nightbane RPG p.92', 'nightbane'),
  ('Appearance: Monstrous Lycanthrope', 'Appearance', 61, 75, 'Monstrous Lycanthrope', 'route', '[{"table": "Animal Form", "count": 1}, {"table": "Stigmata", "count": 1}, {"table": "Nightbane Characteristics", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'Not only is the Morphus form animal-like, it has hideous deformities that give it a terrifying appearance.', NULL, 'import', 'Nightbane RPG p.92', 'nightbane'),
  ('Appearance: Inhuman Shape', 'Appearance', 76, 90, 'Inhuman Shape', 'route', '[{"table": "Stigmata", "count": 1}, {"table": "Nightbane Characteristics", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'The Nightbane''s True Shape is a gruesome mockery of humanity.', NULL, 'import', 'Nightbane RPG p.92', 'nightbane'),
  ('Appearance: Bizarre', 'Appearance', 91, 100, 'Bizarre', 'route', '[{"table": "Unearthly Beauty", "count": 1}, {"table": "Nightbane Characteristics", "count": 1}, {"table": "Animal Form", "count": 1}, {"table": "Stigmata", "count": 1}]', 'Roll once on each of the four tables, then exercise your imagination to combine the results into one alien form.', NULL, NULL, NULL, NULL, NULL, NULL, 'import', 'Nightbane RPG p.92', 'nightbane'),
  ('Nightbane Characteristics: Nightbane Characteristics Table', 'Nightbane Characteristics', 0, 0, 'Nightbane Characteristics Table', 'intro', NULL, NULL, NULL, NULL, NULL, NULL, 'Roll or select one category to determine an unusual characteristic. Some results (81-90/91-95/96-00) call for rolling or selecting two, three or four categories at once instead of one.', NULL, 'import', 'Nightbane RPG p.92', 'nightbane'),
  ('Nightbane Characteristics: Unusual Facial Features', 'Nightbane Characteristics', 1, 20, 'Unusual Facial Features', 'route', '[{"table": "Unusual Facial Features", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'Roll on the Unusual Facial Features Table.', NULL, 'import', 'Nightbane RPG p.92', 'nightbane'),
  ('Nightbane Characteristics: Biomechanical', 'Nightbane Characteristics', 21, 40, 'Biomechanical', 'route', '[{"table": "Biomechanical", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'Roll on the Biomechanical Table.', NULL, 'import', 'Nightbane RPG p.92', 'nightbane'),
  ('Nightbane Characteristics: Alien Creature', 'Nightbane Characteristics', 41, 60, 'Alien Creature', 'route', '[{"table": "Alien Shape", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'Roll on the Alien Shape Table.', 'Printed entry name is Alien Creature; it routes to the table headed Alien Shape Table in the book (the canonical name used above in routes).', 'import', 'Nightbane RPG p.92', 'nightbane'),
  ('Nightbane Characteristics: Unnatural Limbs', 'Nightbane Characteristics', 61, 80, 'Unnatural Limbs', 'route', '[{"table": "Unnatural Limbs", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'Roll on the Unnatural Limbs Table.', NULL, 'import', 'Nightbane RPG p.92', 'nightbane'),
  ('Nightbane Characteristics: Two characteristics', 'Nightbane Characteristics', 81, 90, 'Two characteristics', 'combination', '[{"table": "Nightbane Characteristics", "count": 2}]', 'Roll or select two categories. Ignore any result of 61% or higher (alternatively, roll 1D6x10% to get a result between 10-60%). If the same category comes up twice, roll twice on that table.', NULL, NULL, NULL, NULL, NULL, 'As printed, ignore any result of 61% or higher also excludes 61-80 Unnatural Limbs from this multi-pick (the 1D6x10% alternative tops out at 60 too), which reads like a possible erratum (perhaps 81% was meant). Reported as printed; see morphus-map.md headline finding 2.', 'import', 'Nightbane RPG p.92', 'nightbane'),
  ('Nightbane Characteristics: Three characteristics', 'Nightbane Characteristics', 91, 95, 'Three characteristics', 'combination', '[{"table": "Nightbane Characteristics", "count": 3}]', 'Roll or select three categories. Ignore any result of 61% or higher (alternatively, roll 1D6x10% to get a result between 10-60%). If the same category comes up twice, roll twice on that table.', NULL, NULL, NULL, NULL, NULL, 'Same 61%-or-higher exclusion as the 81-90 row; see that row''s note.', 'import', 'Nightbane RPG p.92', 'nightbane'),
  ('Nightbane Characteristics: Four Characteristics', 'Nightbane Characteristics', 96, 100, 'Four Characteristics', 'combination', '[{"table": "Nightbane Characteristics", "count": 4}]', 'As the Two/Three characteristics rows, but roll four times, ignoring any result of 61% or higher (or roll 1D6x10% for 10-60%).', NULL, NULL, NULL, NULL, NULL, 'Same 61%-or-higher exclusion as the 81-90 row; see that row''s note.', 'import', 'Nightbane RPG p.92', 'nightbane'),
  ('Unearthly Beauty: Unearthly Beauty Table', 'Unearthly Beauty', 0, 0, 'Unearthly Beauty Table', 'intro', NULL, NULL, NULL, NULL, NULL, NULL, 'Roll or select one. Not all Morphus are horrible: some Nightbane manifest a terrible beauty that produces fascination and awe instead of fear or loathing. Beautiful Nightbane are nicknamed Barbie or Ken (older Nightbane: Venus or Adonis) and often draw jealousy and contempt from other Nightbane.', NULL, 'import', 'Nightbane RPG p.92-93', 'nightbane'),
  ('Unearthly Beauty: Doll-Like Appearance', 'Unearthly Beauty', 1, 10, 'Doll-Like Appearance', 'effect', NULL, NULL, '{"attributes": {"PB": 6}}', NULL, 10, NULL, 'Body becomes small and toy-like; skin unnaturally smooth and featureless (no fingerprints); size reduced by 2D6+10 inches (0.3 to 0.55 m); body temperature inhumanly cold. From a distance mistaken for a small child; if standing perfectly still might pass as a storefront mannequin. In good light, the inhuman features look frightening.', NULL, 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Unearthly Beauty: Animal Magnetism', 'Unearthly Beauty', 11, 30, 'Animal Magnetism', 'effect', NULL, NULL, '{"attributes": {"PB": 8, "MA": 8}}', NULL, NULL, NULL, 'P.B. and M.A. increased by 8 (minimum P.B. and M.A. of 20). The Morphus is incredibly beautiful and radiates charisma, but the attraction cannot be turned off, leading to distractions, annoyances and even hazards as strangers make advances or force their affections on the character.', NULL, 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Unearthly Beauty: Elfin Features', 'Unearthly Beauty', 31, 50, 'Elfin Features', 'effect', NULL, NULL, '{"attributes": {"PB": 7}}', NULL, 6, NULL, 'Slender, delicate features, oversized eyes and vaguely pointed ears (minimum P.B. 17); size increases by 1D6 inches.', NULL, 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Unearthly Beauty: Physical Perfection', 'Unearthly Beauty', 51, 70, 'Physical Perfection', 'effect', NULL, NULL, '{"attributes": {"PB": "1d4", "PE": "1d4", "PS": "1d4"}, "pools": {"sdc": "4d6"}}', NULL, 6, NULL, 'True Shape at the peak of physical condition, with perfectly delineated muscles, a build somewhere between a gymnast and a bodybuilder. Projects an aura of danger that intimidates those around the character.', NULL, 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Unearthly Beauty: Fallen Angel', 'Unearthly Beauty', 71, 90, 'Fallen Angel', 'effect', NULL, NULL, '{"attributes": {"PB": 6}, "pools": {"sdc": "3d6"}}', NULL, NULL, NULL, 'Inhuman beauty. Feathered wings on the back provide slow flight, flying Speed 4D6.', NULL, 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Unearthly Beauty: Combination of Two', 'Unearthly Beauty', 91, 95, 'Combination of Two', 'combination', '[{"table": "Unearthly Beauty", "count": 2}]', 'Roll two times (ignore and reroll any result of 91% or higher) and combine the two results.', NULL, NULL, NULL, NULL, NULL, NULL, 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Unearthly Beauty: Other', 'Unearthly Beauty', 96, 100, 'Other', 'combination', '[{"table": "Unearthly Beauty", "count": 3}]', 'The Game Master and player may instead invent a different form of unearthly beauty, balanced by an inhuman or intimidating feature. Alternatively, roll three times (ignore and reroll any result of 91% or higher, as per 91-95%) and combine the results.', NULL, NULL, NULL, '["GM/player-invented form of beauty", "roll three times and combine, as per 91-95%"]', NULL, NULL, 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Animal Form: Animal Form Table', 'Animal Form', 0, 0, 'Animal Form Table', 'intro', NULL, NULL, NULL, NULL, NULL, NULL, 'Roll or select one; the actual animal species within a result is always the player''s choice. All animal forms are capable of full human speech (the words may be twisted by the Nightbane''s inhuman shape, or perfectly human-like, player''s choice); hearing words from an animal adds +1 to the Horror Factor of the creature the first few times a listener hears it, until they get accustomed to it.', '01-07 Bear and 08-14 Amphibian route to a Bear Table and an Amphibian Table that are not printed anywhere in the 248-page cache for this book; see the note on those two rows.', 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Animal Form: Bear', 'Animal Form', 1, 7, 'Bear', 'route', '[{"table": "Bear", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'All large ursinoids.', 'Routes to a Bear Table as printed. No such table exists anywhere in the cached book (checked against the full text layer); this row names the destination exactly as printed.', 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Animal Form: Amphibian', 'Animal Form', 8, 14, 'Amphibian', 'route', '[{"table": "Amphibian", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'Mostly frogs and toads.', 'Routes to an Amphibian Table as printed. No such table exists anywhere in the cached book (checked against the full text layer); this row names the destination exactly as printed.', 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Animal Form: Insectoid', 'Animal Form', 15, 20, 'Insectoid', 'route', '[{"table": "Insectoid", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'All types of insects, from beautiful butterflies to disgusting dung beetles.', NULL, 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Animal Form: Rodent', 'Animal Form', 21, 27, 'Rodent', 'route', '[{"table": "Rodent", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'Rats, squirrels, beavers and similar creatures. City-bred Nightbane tend to favor rats, while those from the country often transform into wilderness varieties.', NULL, 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Animal Form: Arachnid', 'Animal Form', 28, 35, 'Arachnid', 'route', '[{"table": "Arachnid", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'Spiders and scorpions.', NULL, 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Animal Form: Bat', 'Animal Form', 36, 44, 'Bat', 'route', '[{"table": "Bat", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'All varieties of pointy-eared flying mammals, including vampire bats, fox-bats, and others.', NULL, 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Animal Form: Feline', 'Animal Form', 45, 53, 'Feline', 'route', '[{"table": "Feline", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'All cats, from the great predators to small house cats.', NULL, 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Animal Form: Snake', 'Animal Form', 54, 62, 'Snake', 'route', '[{"table": "Snake", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'All crawling, non-legged, scaly creatures, from the huge anaconda to the tiniest garden snake.', NULL, 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Animal Form: Avian', 'Animal Form', 63, 71, 'Avian', 'route', '[{"table": "Avian/Bird", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'Any bird species can be selected (most of them are predatorial or scavenging birds).', 'Printed entry name is Avian; it routes to the table headed Avian/Bird Table (the canonical name used above in routes).', 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Animal Form: Canine', 'Animal Form', 72, 79, 'Canine', 'route', '[{"table": "Canine", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'Dogs, wolves and foxes.', NULL, 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Animal Form: Reptilian', 'Animal Form', 80, 88, 'Reptilian', 'route', '[{"table": "Reptilian", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'Lizards (snakes have their own table) of all kinds.', NULL, 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Animal Form: Equine/Bovine/Deer', 'Animal Form', 89, 95, 'Equine/Bovine/Deer', 'route', '[{"table": "Equine/Bovine/Deer", "count": 1}]', NULL, NULL, NULL, NULL, NULL, 'Includes not only horses and cows, but all kinds of hoofed plant-eaters such as goats, deer, antelope, zebras, etc.', NULL, 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Animal Form: Combination of Two', 'Animal Form', 96, 98, 'Combination of Two', 'combination', '[{"table": "Animal Form", "count": 2}]', 'Roll twice on this table (ignore and reroll any result of 96% or higher), and combine the elements from the two animals. To decide which bonuses apply, roll 1D6 per attribute: 1-3 uses the first animal''s bonus, 4-6 the second''s.', NULL, NULL, NULL, NULL, NULL, NULL, 'import', 'Nightbane RPG p.93', 'nightbane'),
  ('Animal Form: Combination of Three', 'Animal Form', 99, 100, 'Combination of Three', 'combination', '[{"table": "Animal Form", "count": 3}]', 'Roll three times (ignore and reroll any result of 96% or higher) and combine elements from the three animals. To decide which bonuses apply to each attribute, roll 1D6: 1-2 first animal, 3-4 second, 5-6 third.', NULL, NULL, NULL, NULL, NULL, NULL, 'import', 'Nightbane RPG p.94', 'nightbane'),
  ('Stigmata: Stigmata Table', 'Stigmata', 0, 0, 'Stigmata Table', 'intro', NULL, NULL, NULL, NULL, NULL, NULL, 'Roll percentile dice. Stigmata are wounds, sores or embedded objects that never heal and mark the Nightbane''s Morphus as visibly injured; often read as an embodiment of guilt or psychological trauma, or a memory of wounds suffered around the time of the character''s Becoming.', NULL, 'import', 'Nightbane RPG p.101', 'nightbane');
INSERT INTO morphus_characteristics
  (key, table_name, roll_low, roll_high, name, kind, routes, route_rule, bonuses, horror_factor, horror_factor_set, sub_choices, description, note, source, source_book, system)
VALUES
  ('Stigmata: Bloody Ooze', 'Stigmata', 1, 5, 'Bloody Ooze', 'effect', NULL, NULL, NULL, '1d4', NULL, NULL, 'Covered in a slimy, blood-like liquid, making the skin slippery: +2 to parry/dodge against pins or grappling attacks.', NULL, 'import', 'Nightbane RPG p.101', 'nightbane'),
  ('Stigmata: Corpse-Like', 'Stigmata', 6, 10, 'Corpse-Like', 'effect', NULL, NULL, '{"pools": {"sdc": "3d6"}}', '1d4', NULL, NULL, 'Skin is grayish-green, eyes sunken, looks like a days-old corpse, complete with the odor of death and signs of decay. Reduce P.B. by 25%.', NULL, 'import', 'Nightbane RPG p.101', 'nightbane'),
  ('Stigmata: Stitches', 'Stigmata', 11, 15, 'Stitches', 'effect', NULL, NULL, '{"pools": {"sdc": "3d6"}}', '1d4', NULL, NULL, 'A crisscrossing of stitches at several points in the skin gives the appearance of a rebuilt corpse; limbs and body may not quite match (e.g. sewn-on limbs belonging to an animal, with a human-like torso and head). Particularly appropriate for lycanthrope Nightbane who bear stigmata.', NULL, 'import', 'Nightbane RPG p.101', 'nightbane'),
  ('Stigmata: Nails', 'Stigmata', 16, 23, 'Nails', 'effect', NULL, NULL, '{"pools": {"sdc": "4d6"}}', NULL, NULL, '["localized to a few small areas (eyes, forehead, hands, shoulders, torso, etc.)", "completely covering the character"]', 'Metal nails, pins, spikes or screws protrude from the skin. If completely covered, a body slam inflicts 2D6 plus normal punch damage.', 'The book prints no Horror Factor bonus for this entry (every other Stigmata leaf entry has one).', 'import', 'Nightbane RPG p.101', 'nightbane'),
  ('Stigmata: Razor Blades', 'Stigmata', 24, 31, 'Razor Blades', 'effect', NULL, NULL, '{"pools": {"sdc": "4d6"}}', '1d4+1', NULL, '["fingernails replaced with razors (+1D6 to hand to hand damage)", "razor blades in the mouth (bite inflicts 2D6)", "razor blades on the skin (body slam inflicts 2D6 plus normal punch damage)"]', 'Razor blades are unnaturally attached to the Nightbane, replacing teeth or fingernails, or covering the character like a porcupine''s quills.', NULL, 'import', 'Nightbane RPG p.101', 'nightbane'),
  ('Stigmata: Broken Glass', 'Stigmata', 32, 39, 'Broken Glass', 'effect', NULL, NULL, '{"pools": {"sdc": "3d6"}}', '1d4', NULL, NULL, 'Jagged pieces of glass are embedded in the character''s flesh, in small specific areas or covering the body. Same damage options as Razor Blades.', NULL, 'import', 'Nightbane RPG p.101', 'nightbane'),
  ('Stigmata: Barbed Wire/Razor Wire', 'Stigmata', 40, 47, 'Barbed Wire/Razor Wire', 'effect', NULL, NULL, '{"pools": {"sdc": "4d6"}}', '1d4', NULL, NULL, 'Part of the character''s limbs, head, neck or torso are wrapped in barbed or razor wire, causing bloody wounds that never heal. Same damage options as Razor Blades.', NULL, 'import', 'Nightbane RPG p.102', 'nightbane'),
  ('Stigmata: Eternal Wounds', 'Stigmata', 48, 55, 'Eternal Wounds', 'effect', NULL, NULL, '{"pools": {"sdc": "3d6"}}', '1d4', NULL, NULL, 'Horrible wounds that never heal, most often clearly visible and appearing deadly: gaping chest wounds, gashes in the skull, cuts, gouges and other grotesqueries. The wounds cover any clothes the character wears with bloody patches within minutes, soaking through bandages and dressings after a while.', NULL, 'import', 'Nightbane RPG p.102', 'nightbane'),
  ('Stigmata: Missing Skin', 'Stigmata', 56, 63, 'Missing Skin', 'effect', NULL, NULL, '{"pools": {"sdc": "3d6"}}', '1d4+1', NULL, '["patches of skin missing", "the whole skin missing"]', 'Patches of skin, or the whole skin, are missing (player''s choice), revealing bare muscle and bones.', NULL, 'import', 'Nightbane RPG p.102', 'nightbane'),
  ('Stigmata: Leatherboy/girl', 'Stigmata', 64, 71, 'Leatherboy/girl', 'effect', NULL, NULL, '{"pools": {"sdc": "5d6"}}', '1d4', NULL, NULL, 'Portions (or all) of the Nightbane''s skin seems to have been replaced with shiny, polished leather, belts, bodysuits and the like. S&M gear like hoods and straps are not uncommon, all grafted to the skin and flesh; metal studs, chains and other decorations finish the grotesque design.', NULL, 'import', 'Nightbane RPG p.102', 'nightbane'),
  ('Stigmata: Boils or Sores', 'Stigmata', 72, 79, 'Boils or Sores', 'effect', NULL, NULL, '{"pools": {"sdc": "3d6"}}', '2', NULL, NULL, 'Areas of the character''s body are covered in open sores or festering boils.', NULL, 'import', 'Nightbane RPG p.102', 'nightbane'),
  ('Stigmata: Zippers', 'Stigmata', 80, 85, 'Zippers', 'effect', NULL, NULL, '{"pools": {"sdc": "3d6"}}', '1', NULL, NULL, 'Zippers close horrible wounds in the character''s body. The Horror Factor is increased by an additional 3 if the Nightbane opens a zipper to reveal the pulsing flesh or organs underneath.', NULL, 'import', 'Nightbane RPG p.102', 'nightbane'),
  ('Stigmata: Bones', 'Stigmata', 86, 90, 'Bones', 'effect', NULL, NULL, '{"pools": {"sdc": "5d6x10"}}', '1d4+1', NULL, NULL, 'Some (or even all) of the Nightbane''s body has been stripped of flesh and muscle to reveal bare bone.', NULL, 'import', 'Nightbane RPG p.102', 'nightbane'),
  ('Stigmata: Biomechanical', 'Stigmata', 91, 96, 'Biomechanical', 'route', '[{"table": "Biomechanical", "count": 1}]', 'Roll on the Biomechanical Table; the result appears as a bloody wound or sore where the mechanical part is attached or placed (e.g. an Armorgraft result looks nailed or hammered into the flesh, its edges patina''d with fresh blood).', NULL, '1', NULL, NULL, 'Add 1 point to the Horror Factor already associated with the rolled Biomechanical result.', NULL, 'import', 'Nightbane RPG p.102', 'nightbane'),
  ('Stigmata: Combination of Two', 'Stigmata', 97, 100, 'Combination of Two', 'combination', '[{"table": "Stigmata", "count": 2}]', 'Roll two times (ignore and reroll any result of 97% or higher) and combine the two characteristics and their Horror Factor points (added together).', NULL, NULL, NULL, NULL, NULL, NULL, 'import', 'Nightbane RPG p.102', 'nightbane'),
  ('Unusual Facial Features: Unusual Facial Features Table', 'Unusual Facial Features', 0, 0, 'Unusual Facial Features Table', 'intro', NULL, NULL, NULL, NULL, NULL, NULL, 'Many Nightbane appear completely normal from a distance - until one looks them in the face.', NULL, 'import', 'Nightbane RPG p.102', 'nightbane'),
  ('Unusual Facial Features: Oversized Carnivorous Mouth', 'Unusual Facial Features', 1, 7, 'Oversized Carnivorous Mouth', 'effect', NULL, NULL, NULL, '1', NULL, NULL, 'Supernaturally strong jaw muscles inflict 2D6 S.D.C. with a bite. The character can hold on and continue biting (no attack roll necessary after the first; inflicts normal bite damage once at the beginning and once at the end of the round until dislodged or the character lets go; no other combat actions possible while using this attack).', NULL, 'import', 'Nightbane RPG p.102', 'nightbane'),
  ('Unusual Facial Features: Glowing Eyes', 'Unusual Facial Features', 8, 15, 'Glowing Eyes', 'effect', NULL, NULL, NULL, '1', NULL, NULL, 'Eyes glow with unnatural light, bright enough to faintly illuminate a dark area. Normal sunglasses will not hide the glow, but mirror shades will. Enhanced nightvision, range 2000 feet (610 m).', NULL, 'import', 'Nightbane RPG p.102', 'nightbane'),
  ('Unusual Facial Features: Cyclops', 'Unusual Facial Features', 16, 22, 'Cyclops', 'effect', NULL, NULL, NULL, '2', NULL, NULL, 'One large eye in the middle of the forehead; perfect 20/20 vision.', NULL, 'import', 'Nightbane RPG p.102', 'nightbane'),
  ('Unusual Facial Features: Misshapen Facial Features', 'Unusual Facial Features', 23, 30, 'Misshapen Facial Features', 'effect', NULL, NULL, NULL, '1d4', NULL, NULL, 'Possibilities include: eyes in the wrong place, a flat or missing nose, the mouth where the eyes should be and vice versa, more than one mouth, and other bizarre features.', NULL, 'import', 'Nightbane RPG p.102', 'nightbane'),
  ('Unusual Facial Features: Extra Eyes', 'Unusual Facial Features', 31, 38, 'Extra Eyes', 'effect', NULL, NULL, '{"combat": {"perception": 2}}', '1d4', NULL, '["roll 1D4 additional eyes", "choose a total of 1-6 eyes"]', 'Additional eyes arranged in two or three rows, human-sized or slightly smaller. Bonus is to perception rolls involving sight.', NULL, 'import', 'Nightbane RPG p.102', 'nightbane'),
  ('Unusual Facial Features: Sharp Teeth', 'Unusual Facial Features', 39, 46, 'Sharp Teeth', 'effect', NULL, NULL, NULL, NULL, NULL, NULL, 'Long fang-like teeth; bite inflicts 3D6 damage. Add 2 to Horror Factor whenever the teeth are displayed (in a smile, for example).', NULL, 'import', 'Nightbane RPG p.102', 'nightbane'),
  ('Unusual Facial Features: Skull Face', 'Unusual Facial Features', 47, 55, 'Skull Face', 'effect', NULL, NULL, '{"pools": {"sdc": "2d4"}}', '1d4', NULL, '["surrounded by a nimbus of light or flames (1-30%)", "completely fleshless and bare, protruding grotesquely from a flesh neck (31-60%)", "looks more like a bony helmet or mask than a real head (61-90%)", "different, unusual look (91-00%); the player may roll again on this table for a further deformity such as small horns or additional eye sockets"]', 'The character''s head is a fleshless skull (players may opt to let hair grow on the skull, or leave it bare); has its own sub-roll (or pick) for the specific look, see sub_choices.', NULL, 'import', 'Nightbane RPG p.102-103', 'nightbane'),
  ('Unusual Facial Features: Small Horns', 'Unusual Facial Features', 56, 62, 'Small Horns', 'effect', NULL, NULL, NULL, '1', NULL, NULL, 'Small, vestigial horns, typically similar to a goat''s or a ram''s; can be disguised with a hat or other head covering. Head butt does 1D6 S.D.C. in addition to normal punch damage.', NULL, 'import', 'Nightbane RPG p.103', 'nightbane'),
  ('Unusual Facial Features: Large Horns', 'Unusual Facial Features', 63, 70, 'Large Horns', 'effect', NULL, NULL, NULL, '2', NULL, NULL, 'Horns often similar to a ram''s or deer''s, so large that it is almost impossible to hide them. A head-butt inflicts 3D6 S.D.C. in addition to normal punch damage.', NULL, 'import', 'Nightbane RPG p.103', 'nightbane'),
  ('Unusual Facial Features: Facial Tentacles', 'Unusual Facial Features', 71, 78, 'Facial Tentacles', 'effect', NULL, NULL, '{"pools": {"sdc": "1d6"}}', '1d4', NULL, NULL, 'Writhing tentacles protrude from the face; can be situated anywhere (e.g. the chin for a living beard look, between the nose and mouth for a Lovecraftian appearance, or instead of hair for a Medusa-like look).', NULL, 'import', 'Nightbane RPG p.103', 'nightbane'),
  ('Unusual Facial Features: No Face', 'Unusual Facial Features', 79, 85, 'No Face', 'effect', NULL, NULL, NULL, '1d4', NULL, NULL, 'A perfectly smooth face: no eyes, mouth or nose are visible. The character can speak, but the voice seems to come from inside the smooth surface, with an inhuman quality or simply muffled (player''s choice). The lack of eyes does not impair the Nightbane''s senses (sees, smells and hears perfectly). To eat, food is seemingly pushed through the skin like a soft membrane where the mouth should be.', NULL, 'import', 'Nightbane RPG p.103', 'nightbane'),
  ('Unusual Facial Features: Biomechanical', 'Unusual Facial Features', 86, 90, 'Biomechanical', 'route', '[{"table": "Biomechanical", "count": 1}]', 'Roll on the Biomechanical Table, but only apply the result to the face/head of the Nightbane; the rest of the body may be normal or have completely different characteristics.', NULL, NULL, NULL, NULL, NULL, NULL, 'import', 'Nightbane RPG p.103', 'nightbane'),
  ('Unusual Facial Features: Alien Features', 'Unusual Facial Features', 91, 95, 'Alien Features', 'effect', NULL, NULL, NULL, '2', NULL, NULL, 'The Nightbane looks inhuman and alien: the head may be oversized with large (or small), black, almond-shaped eyes, a tiny nose or nose holes, no facial hair, dark or pale complexion, and other inhuman features (fangs, skin patterns, horns, etc.).', NULL, 'import', 'Nightbane RPG p.103', 'nightbane'),
  ('Unusual Facial Features: Two', 'Unusual Facial Features', 96, 98, 'Two', 'combination', '[{"table": "Unusual Facial Features", "count": 2}]', 'Roll twice (ignore and reroll any result of 96% or higher) and try to combine the results (e.g. Cyclops + No Face = one central eye and no other facial features).', NULL, NULL, NULL, NULL, NULL, NULL, 'import', 'Nightbane RPG p.103', 'nightbane'),
  ('Unusual Facial Features: Three', 'Unusual Facial Features', 99, 100, 'Three', 'combination', '[{"table": "Unusual Facial Features", "count": 3}]', 'As the Two result, but roll three times.', NULL, NULL, NULL, NULL, NULL, NULL, 'import', 'Nightbane RPG p.103', 'nightbane'),
  ('Arachnid: Arachnid Table', 'Arachnid', 0, 0, 'Arachnid Table', 'intro', NULL, NULL, NULL, NULL, NULL, NULL, 'Roll or select. All arachnid characters instinctively have the base skills of climb at 55% and prowl at 25% whenever they change into their Morphus shape. Player chooses spider or scorpion for each entry.', NULL, 'import', 'Nightbane RPG p.94', 'nightbane'),
  ('Arachnid: Full Arachnid', 'Arachnid', 1, 20, 'Full Arachnid', 'effect', NULL, NULL, '{"attributes": {"PS": 4, "PP": 2, "PE": 2, "Spd": "1d4x10"}, "combat": {"initiative": 2, "perception": 1}, "pools": {"sdc": "3d6x10"}}', '6', NULL, '["spider", "scorpion"]', 'Morphus is a giant spider or scorpion; can leap 20 feet. If spider: spins/shoots webbing (range 60 ft, 4D6 S.D.C. per length/application), bite 2D4 plus poison 4D6 S.D.C. (2D6 if victim saves vs lethal poison). If scorpion: pincers add one attack per melee and 3D6 S.D.C. hand to hand damage, stinger inflicts 3D6 S.D.C. plus poison (same as spider''s).', NULL, 'import', 'Nightbane RPG p.94', 'nightbane'),
  ('Arachnid: Were-Arachnid', 'Arachnid', 21, 45, 'Were-Arachnid', 'effect', NULL, NULL, '{"attributes": {"PS": 2, "PP": 2, "Spd": "2d6"}, "combat": {"initiative": 1, "perception": 1, "attacks": 1}, "pools": {"sdc": "2d4x10"}}', '1d4+2', NULL, '["spider", "scorpion"]', 'Vaguely humanoid: two legs and six arms if a spider, or two legs, two arms, two additional arms with pincers and a tail/stinger if a scorpion; head has four to six eyes, pincer-mouth, chitin or spider-fur; can leap 10 feet. Extra attack from the extra limbs. If spider: webbing range 60 ft with 3D6 S.D.C. per application, bite 1D6 plus poison 4D6 S.D.C. (2D6 if save). If scorpion: pincers add 2D6 to hand to hand damage, stinger inflicts 3D6 S.D.C. plus poison (same as spider''s).', NULL, 'import', 'Nightbane RPG p.94', 'nightbane'),
  ('Arachnid: Humanoid-Arachnid', 'Arachnid', 46, 70, 'Humanoid-Arachnid', 'effect', NULL, NULL, '{"attributes": {"PS": 2, "PP": 1, "Spd": "1d6"}, "pools": {"sdc": "1d6x10"}}', '1d4', NULL, '["spider", "scorpion"]', '"Man-spider" or "man-scorpion": mostly humanoid shape with chitin or hair-covered skin, clawed hands, and either two additional spider-arms or a scorpion''s stinger; can leap 6 feet. If spider: extra attack per melee from the extra arms, clawed limbs inflict 3D6 in addition to hand to hand damage. If scorpion: extra attack per melee from the stinger, which inflicts 2D6 S.D.C. plus poison doing 4D6 S.D.C. (2D6 if a save vs lethal poison is made).', NULL, 'import', 'Nightbane RPG p.94', 'nightbane'),
  ('Arachnid: Scorpion Pincers/Spider Limbs', 'Arachnid', 71, 90, 'Scorpion Pincers/Spider Limbs', 'effect', NULL, NULL, '{"attributes": {"PS": 2, "PE": 1}, "pools": {"sdc": "3d6"}}', '1', NULL, '["Scorpion Pincers", "Spider Limbs"]', 'Normal human shape except the hands, tipped by either pincers or bony hair-covered fingers with claws; predatory look. Pincers inflict 3D6 in addition to normal hand to hand damage; spider-clawed hands do 2D6 damage. Cannot grasp tools/weapons properly: -5 to use them and -30% to skill proficiencies requiring dexterity and sensitive touch.', NULL, 'import', 'Nightbane RPG p.94', 'nightbane'),
  ('Arachnid: Spider/Scorpion Centauroid', 'Arachnid', 91, 100, 'Spider/Scorpion Centauroid', 'effect', NULL, NULL, '{"attributes": {"PS": 2, "PP": 2, "PE": 1, "Spd": "3d6"}, "pools": {"sdc": "3d6x10"}}', '1d6', NULL, '["spider", "scorpion"]', 'Huge creature with the lower body of a spider or scorpion and the upper body of a humanoid-arachnid; taller and heavier than a normal human, hard to fit into vehicles/enclosed spaces; can leap 12 feet. If spider: spins/shoots webbing, bite inflicts 2D4 S.D.C. plus poison same as the giant spider. If scorpion: pincers add 3D6 to hand to hand damage, stinger inflicts 3D6 S.D.C. plus poison (same as spider''s).', NULL, 'import', 'Nightbane RPG p.94', 'nightbane'),
  ('Avian/Bird: Avian/Bird Table', 'Avian/Bird', 0, 0, 'Avian/Bird Table', 'intro', NULL, NULL, NULL, NULL, NULL, NULL, 'Roll or select. The player gets to select the bird''s species (most are predatorial or scavenger birds, but any species is possible). No table-wide innate skill is granted.', NULL, 'import', 'Nightbane RPG p.94', 'nightbane'),
  ('Avian/Bird: Full Bird Form', 'Avian/Bird', 1, 15, 'Full Bird Form', 'effect', NULL, NULL, '{"attributes": {"PS": 1, "PP": 3}, "combat": {"initiative": 2, "perception": 3}, "pools": {"sdc": "3d6"}}', '1d4', NULL, NULL, 'Almost no humanoid features; basically a giant bird of the player''s choice. Flying speed 2D6x10. Exceptional vision (can see a rabbit, or read a sign two miles away); the perception bonus applies to sight only. Beak slash/peck does 3D6 S.D.C. plus P.S. bonus. Feet claws add 1D6 S.D.C. to kick damage. Cannot manipulate guns and normal weapons (arms replaced by wings); most skills requiring manual dexterity are at -40%.', NULL, 'import', 'Nightbane RPG p.94', 'nightbane'),
  ('Avian/Bird: Were-Bird', 'Avian/Bird', 16, 30, 'Were-Bird', 'effect', NULL, NULL, '{"attributes": {"PS": 2, "PP": 2}, "combat": {"initiative": 2, "perception": 2}, "pools": {"sdc": "3d6"}}', '1d6', NULL, NULL, 'Bird-man (or woman): hands at the end of the wings, a full bird''s head, clawed feet, and a feather-covered body. Flying speed 2D4x10. Exceptional vision; perception bonus applies to sight only. Beak slash/peck does 2D6 S.D.C. plus P.S. bonus. Feet claws add 1D6 S.D.C. to kick damage. Guns and hand weapons are at -4 to strike; skills requiring manual dexterity are at -25%.', NULL, 'import', 'Nightbane RPG p.94', 'nightbane');
INSERT INTO morphus_characteristics
  (key, table_name, roll_low, roll_high, name, kind, routes, route_rule, bonuses, horror_factor, horror_factor_set, sub_choices, description, note, source, source_book, system)
VALUES
  ('Avian/Bird: Man-Bird', 'Avian/Bird', 31, 45, 'Man-Bird', 'effect', NULL, NULL, '{"attributes": {"PS": 2, "PP": 2}, "combat": {"initiative": 1, "perception": 2}, "pools": {"sdc": "3d6"}}', '1d6', NULL, NULL, 'Separate wings and arms, fully developed hands ending in claws; body still covered by feathers, small beak nearly useless in combat. Exceptional vision; perception bonus applies to sight only. Beak bite does 1D4 S.D.C. (no P.S. bonus). Flying speed is 1D6x10.', NULL, 'import', 'Nightbane RPG p.94-95', 'nightbane'),
  ('Avian/Bird: Bird Head', 'Avian/Bird', 46, 55, 'Bird Head', 'effect', NULL, NULL, '{"combat": {"initiative": 1, "perception": 2}}', '1d6', NULL, NULL, 'Normal human body except the head, which is a bird''s. Beak slash inflicts 3D6 S.D.C. plus P.S. bonus. Exceptional vision; perception bonus applies to sight only.', NULL, 'import', 'Nightbane RPG p.95', 'nightbane'),
  ('Avian/Bird: Bird Face', 'Avian/Bird', 56, 66, 'Bird Face', 'effect', NULL, NULL, '{"combat": {"initiative": 1}}', '1d4', NULL, NULL, 'Normal humanoid except for large round eyes and an oversized beak protruding from where the mouth and nose would be. Beak slash does 3D6 S.D.C. plus P.S. bonus.', NULL, 'import', 'Nightbane RPG p.95', 'nightbane'),
  ('Avian/Bird: Talons', 'Avian/Bird', 67, 80, 'Talons', 'effect', NULL, NULL, '{"attributes": {"PS": 1}}', '1d4', NULL, NULL, 'Hands and feet turn into oversized bird-like talons. Claws add 2D4 to punch and kick damage. Normal shoes and gloves are uncomfortable and painful to wear.', NULL, 'import', 'Nightbane RPG p.95', 'nightbane'),
  ('Avian/Bird: Feather "Hair"', 'Avian/Bird', 81, 90, 'Feather "Hair"', 'effect', NULL, NULL, '{"pools": {"sdc": "2d6"}}', '1', NULL, NULL, 'Instead of hair, the head is covered by feathers; small feather growths appear throughout the body.', NULL, 'import', 'Nightbane RPG p.95', 'nightbane'),
  ('Avian/Bird: Winged Human', 'Avian/Bird', 91, 100, 'Winged Human', 'effect', NULL, NULL, '{"attributes": {"PB": 1}, "pools": {"sdc": "2d6"}}', NULL, NULL, NULL, 'Normal-looking human except for wings protruding from the back (any bird species); can fly at a speed of 1D4x10. The book gives no Horror Factor for this entry.', 'No Horror Factor is printed for this entry (only S.D.C., P.B. and flying speed).', 'import', 'Nightbane RPG p.95', 'nightbane'),
  ('Bat: Bat Table', 'Bat', 0, 0, 'Bat Table', 'intro', NULL, NULL, NULL, NULL, NULL, NULL, 'Roll or select. All bat characters instinctively have the base skills of climb at 45% and prowl at 20% whenever they change into their Morphus shape.', NULL, 'import', 'Nightbane RPG p.95', 'nightbane'),
  ('Bat: Full Bat', 'Bat', 1, 20, 'Full Bat', 'effect', NULL, NULL, '{"attributes": {"PS": 2, "PE": 2, "PP": 4}, "combat": {"initiative": 3, "perception": 4}, "pools": {"sdc": "2d4x10"}}', '1d4', NULL, NULL, 'Giant bat, wingspan over 7 feet. Flying speed 1D6x10+20. Ultra-acute hearing; the perception bonus applies to sound only; unlike true bats, vision is not impaired. Arms are giant leathery wings with hands at the middle joint: -6 to strike and -35% to perform skills requiring tools/weapons (both impossible while flying), though it can carry small objects in its hands or larger items/people in its prehensile clawed feet. Clawed feet inflict 2D6 S.D.C. plus hand to hand damage; bite does 2D6 S.D.C. Screeching acts as radar, sensing invisible figures/obstacles in total darkness, fog or smoke, range 500 feet.', NULL, 'import', 'Nightbane RPG p.95', 'nightbane'),
  ('Bat: Were-Bat', 'Bat', 21, 40, 'Were-Bat', 'effect', NULL, NULL, '{"attributes": {"PS": 3, "PP": 3, "PE": 3}, "combat": {"initiative": 1, "perception": 3}, "pools": {"sdc": "1d6x10"}}', '1d6', NULL, NULL, 'More human-like, fur-covered, animalistic head with a snout and oversized bat ears; instead of arms it has full bat-wings ending in large clawed hands that can grasp objects and use tools/weapons (-3 to strike, -15% to perform skills; neither while flying). Flying speed 1D6x10. Perception bonus applies to sound only; vision not impaired. Screeching acts as radar/sonar, sensing invisible figures and seeing with obscured vision, range 200 feet. Claws on hands and feet inflict 2D4 S.D.C. in addition to normal hand to hand damage. Bite does 2D4 S.D.C.', NULL, 'import', 'Nightbane RPG p.95', 'nightbane'),
  ('Bat: Humanoid Bat', 'Bat', 41, 60, 'Humanoid Bat', 'effect', NULL, NULL, '{"attributes": {"PS": 2, "PP": 1}, "combat": {"perception": 2}, "pools": {"sdc": "1d4x10"}}', '1d4', NULL, NULL, 'Skin sparsely covered by fur; face and features mostly humanoid, with small pointy ears and sharp fangs; small bat-wings extend from beneath the arms, making normal clothing very uncomfortable (wings can be folded, restricting movement). Limited flying speed of 1D4x10. Acute hearing; perception bonus applies to sound only; does NOT have the bat''s sonar sense. Claws on hands inflict 1D6 S.D.C. in addition to normal hand to hand damage. Bite does 1D6 S.D.C.', NULL, 'import', 'Nightbane RPG p.95-96', 'nightbane'),
  ('Bat: Bat Wings', 'Bat', 61, 80, 'Bat Wings', 'effect', NULL, NULL, '{"pools": {"sdc": "4d6"}}', '2', NULL, NULL, 'Perfectly normal human except for bat wings protruding from the back, giving a demonic appearance. Wings allow flight at a speed of 1D6x10, and +1 to dodge when flying.', NULL, 'import', 'Nightbane RPG p.96', 'nightbane'),
  ('Bat: Bat Head', 'Bat', 81, 100, 'Bat Head', 'effect', NULL, NULL, '{"combat": {"initiative": 2, "perception": 4}, "pools": {"sdc": "2d6"}}', '2', NULL, NULL, 'Normal human body topped by a perfect bat''s head. Ultra-acute hearing; perception bonus applies to sound only; vision not impaired. Screeching acts as radar, sensing invisible figures and seeing in total darkness, fog or smoke, range 500 feet. Bite inflicts 2D6 S.D.C.', NULL, 'import', 'Nightbane RPG p.96', 'nightbane'),
  ('Canine: Canine Table', 'Canine', 0, 0, 'Canine Table', 'intro', NULL, NULL, NULL, NULL, NULL, NULL, 'Roll or select. The choice of specific canine species (wolf, dog, fox, etc.) is left to the player. All canine characters instinctively get a base skill of track at 40% and swim at 50% whenever they change into their Morphus shape.', NULL, 'import', 'Nightbane RPG p.96', 'nightbane'),
  ('Canine: Full Canine', 'Canine', 1, 20, 'Full Canine', 'effect', NULL, NULL, '{"attributes": {"PS": 5, "PP": 1, "PE": 3, "Spd": 12}, "combat": {"initiative": 1, "perception": 3}, "pools": {"sdc": "2d6x10"}}', '2', NULL, NULL, 'Large canine, commonly a huge wolf or dog that can pass for a normal member of the species unless other Nightbane characteristics apply. +15% to tracking skill (if the character does not have tracking, gains it at +15% in Morphus alone). Bite attacks do 5D6 S.D.C.; can body-slam (equivalent of punch damage) but cannot punch, kick, or use weapons or tools.', NULL, 'import', 'Nightbane RPG p.96', 'nightbane'),
  ('Canine: Were-Canine', 'Canine', 21, 45, 'Were-Canine', 'effect', NULL, NULL, '{"attributes": {"PS": 4, "PP": 1, "PE": 3, "Spd": 6}, "combat": {"initiative": 2, "perception": 2}, "pools": {"sdc": "2d4x10"}}', '1d4+1', NULL, NULL, 'Humanoid-canine with full dog/wolf features, covered in fur, with a tail, bigger than a normal human. Bite attack does 4D6 S.D.C.; claws add 2D4 S.D.C. to hand to hand damage. +10% to tracking skill (if the character does not have tracking, gains it at +10%).', NULL, 'import', 'Nightbane RPG p.96', 'nightbane'),
  ('Canine: Canine Humanoid', 'Canine', 46, 70, 'Canine Humanoid', 'effect', NULL, NULL, '{"attributes": {"PS": 2, "PE": 2, "Spd": 3}, "combat": {"initiative": 1, "perception": 1}, "pools": {"sdc": "1d4x10"}}', '2', NULL, NULL, 'Less extreme "wolf-man": no snout or tail, but covered in fur and has fangs; heavy clothing could disguise it to some degree. Can leap 12 feet high or lengthwise. Bite does 2D6 S.D.C.; claws add 1D6 S.D.C. to hand to hand damage.', NULL, 'import', 'Nightbane RPG p.96', 'nightbane'),
  ('Canine: Canine Centauroid', 'Canine', 71, 80, 'Canine Centauroid', 'effect', NULL, NULL, '{"attributes": {"PS": 6, "PE": 4, "Spd": 4}, "combat": {"initiative": 1, "perception": 2}, "pools": {"sdc": "2d6x10"}}', '1d4', NULL, NULL, 'Upper body of a were-canine and the lower body of a wolf (four-legged); too big to fit inside most automobiles and may not fit in an elevator or other confined spaces. Bite inflicts 4D6 S.D.C.; claws add 2D4 to hand to hand damage.', NULL, 'import', 'Nightbane RPG p.96', 'nightbane'),
  ('Canine: Canine Head', 'Canine', 81, 100, 'Canine Head', 'effect', NULL, NULL, '{"combat": {"initiative": 1, "perception": 2}}', '1', NULL, NULL, 'Normal looking human with the head of a wolf or dog. Bite inflicts 4D6 S.D.C.', NULL, 'import', 'Nightbane RPG p.96', 'nightbane'),
  ('Equine/Bovine/Deer: Equine/Bovine/Deer Table', 'Equine/Bovine/Deer', 0, 0, 'Equine/Bovine/Deer Table', 'intro', NULL, NULL, NULL, NULL, NULL, NULL, 'Roll or select. Covers most four-legged herbivores (horses, cattle, deer, bison, antelope, goats, zebras, etc). Table-wide note: unless otherwise indicated, kicks and head butts inflict double damage (typically 2D6+P.S. bonus) and jump/leap kicks do triple damage; a horned/antlered creature can head-butt for 4D6 damage. All equine/bovine/deer Nightbane instinctively know how to swim at a base proficiency of 65% and climb at 30%.', NULL, 'import', 'Nightbane RPG p.96-97', 'nightbane'),
  ('Equine/Bovine/Deer: Full Horse/Bovine/Deer Form', 'Equine/Bovine/Deer', 1, 20, 'Full Horse/Bovine/Deer Form', 'effect', NULL, NULL, '{"attributes": {"PS": 12, "PP": 3, "PE": 6, "Spd": "1d6x10"}, "combat": {"initiative": 1, "perception": 2}, "pools": {"sdc": "3d6x10"}}', '1d4', NULL, NULL, 'Huge creature of the chosen species; may pass as a normal animal, though bigger than average with a mean or tough appearance. Can leap 10 feet high or 15 feet lengthwise, and gets an automatic dodge (works like a parry, does not use up a melee attack/action). Cannot use any weapons or tools, and may be too large to fit into most vehicles.', NULL, 'import', 'Nightbane RPG p.97', 'nightbane'),
  ('Equine/Bovine/Deer: Half-Man, Half-Animal/Were-Animal/Minotaur', 'Equine/Bovine/Deer', 21, 45, 'Half-Man, Half-Animal/Were-Animal/Minotaur', 'effect', NULL, NULL, '{"attributes": {"PS": 6, "PP": 2, "PE": 4, "Spd": "4d6"}, "combat": {"initiative": 2}, "pools": {"sdc": "2d6x10"}}', '1d4+2', NULL, NULL, 'Basic bipedal shape of a muscle-bound human, covered with fur, hoofed or cloven feet, a tail, and the head of a horse, bull, deer or similar animal (bull form is the traditional minotaur of myth). Kicks and horn attacks inflict an additional 2D6 S.D.C. damage.', NULL, 'import', 'Nightbane RPG p.97', 'nightbane'),
  ('Equine/Bovine/Deer: Humanoid Shape', 'Equine/Bovine/Deer', 46, 66, 'Humanoid Shape', 'effect', NULL, NULL, '{"attributes": {"PS": 4, "PP": 1, "PE": 2, "Spd": "2d6"}, "combat": {"initiative": 1, "perception": 1}, "pools": {"sdc": "1d6x10"}}', '1d4', NULL, NULL, 'Less extreme version of Half-Man, Half-Animal: chest and arms basically human, fur-covered legs and hoofed/cloven feet; head mostly humanoid but likely has horns or antlers and animal features (large eyes, long face, large flat teeth).', NULL, 'import', 'Nightbane RPG p.97', 'nightbane'),
  ('Equine/Bovine/Deer: Centaur/Beast-Man', 'Equine/Bovine/Deer', 67, 90, 'Centaur/Beast-Man', 'effect', NULL, NULL, '{"attributes": {"PS": 6, "PP": 2, "PE": 5, "Spd": "5d6"}, "combat": {"initiative": 2, "perception": 2}, "pools": {"sdc": "3d6x10"}}', '1d4', NULL, NULL, 'Lower body of a horse, deer, moose, bull, or similar animal, and the upper body of a normal man, with horns or antlers crowning the head. Body may be too big to fit in vehicles or maneuver well indoors.', NULL, 'import', 'Nightbane RPG p.97', 'nightbane'),
  ('Equine/Bovine/Deer: Equine/Bovine Head', 'Equine/Bovine/Deer', 91, 100, 'Equine/Bovine Head', 'effect', NULL, NULL, '{"attributes": {"PS": 1, "Spd": "1d6"}, "combat": {"initiative": 1, "perception": 1}, "pools": {"sdc": "3d6"}}', '1d4', NULL, NULL, 'Normal-looking human body with a full animal head.', NULL, 'import', 'Nightbane RPG p.97', 'nightbane'),
  ('Feline: Feline Table', 'Feline', 0, 0, 'Feline Table', 'intro', NULL, NULL, NULL, NULL, NULL, NULL, 'Roll or select. The player selects the species (any feline, from prehistoric sabertooths to household tabbies). All feline characters automatically get a bonus of +2 to roll with fall or impact and instinctively get base skills of climb at 45%, swim at 40% and prowl at 20% whenever they change into their Morphus shape.', NULL, 'import', 'Nightbane RPG p.97', 'nightbane'),
  ('Feline: Full Feline Form', 'Feline', 1, 10, 'Full Feline Form', 'effect', NULL, NULL, '{"attributes": {"PS": 6, "PP": 3, "PE": 3, "Spd": "1d6x10"}, "combat": {"initiative": 2, "perception": 2}, "pools": {"sdc": "3d6x10"}}', '1d4', NULL, NULL, 'Large (or, for household cats, giant) version of the species. Nightvision extended to 1000 feet; the perception bonus applies to sound. Claws add 2D6 S.D.C. to (supernatural) strength damage. Bites inflict 4D6 S.D.C. Can leap 30 feet from a standing position and 60 feet with a running start. Cannot use any weapons, tools or vehicles.', NULL, 'import', 'Nightbane RPG p.97', 'nightbane'),
  ('Feline: Were-Cat', 'Feline', 11, 26, 'Were-Cat', 'effect', NULL, NULL, '{"attributes": {"PS": 4, "PP": 2, "PE": 2, "Spd": "1d4x10"}, "combat": {"initiative": 2, "perception": 2}, "pools": {"sdc": "2d4x10"}}', '1d6', NULL, NULL, 'Humanoid feline creature, covered in fur, with full feline-shaped head and tail. Nightvision extended to 1000 feet; perception bonus applies to sound. Claws add 2D4 S.D.C. to (supernatural) strength damage. Bite inflicts 3D6 S.D.C. Can leap 20 feet standing or 40 feet with a running start. Paws make weapons/tools hard to use: -4 to strike with guns and -20% (or -4) to use weapons, tools or skills requiring manual dexterity.', NULL, 'import', 'Nightbane RPG p.97', 'nightbane'),
  ('Feline: Fur-Covered Humanoid', 'Feline', 27, 42, 'Fur-Covered Humanoid', 'effect', NULL, NULL, '{"attributes": {"PS": 2, "PP": 2, "Spd": "3d6"}, "combat": {"initiative": 1, "perception": 2}, "pools": {"sdc": "1d6x10"}}', '1d4', NULL, NULL, 'Could pass for human in bad light; skin covered with fur, feline ears near the top of the head, sharp feline fangs, a long furry tail, vertical-slit eyes. Claws add 1D6 S.D.C. to (supernatural) damage. Bite inflicts 2D6 S.D.C. Nightvision 800 feet; perception bonus applies to sound.', NULL, 'import', 'Nightbane RPG p.97', 'nightbane'),
  ('Feline: Cat-like', 'Feline', 43, 58, 'Cat-like', 'effect', NULL, NULL, '{"attributes": {"PP": 1, "Spd": "1d6"}, "combat": {"perception": 1}}', '1d4', NULL, NULL, 'Appears to be a normal person except for vertical-slit eyes, unnaturally long and sharp teeth, and retractable claws in the hands and feet. Nightvision 800 feet; perception bonus applies to sound. Claws add 1D6 S.D.C. to (supernatural) damage. Bite inflicts 2D6 S.D.C.', NULL, 'import', 'Nightbane RPG p.97', 'nightbane'),
  ('Feline: Feline Centauroid', 'Feline', 59, 69, 'Feline Centauroid', 'effect', NULL, NULL, '{"attributes": {"PS": 6, "PP": 2, "PE": 4, "Spd": "1d6x10"}, "pools": {"sdc": "3d6x10"}}', '1d6', NULL, NULL, 'Lower body of a giant cat and the upper body of a were-cat; almost as big as a horse, cannot fit in most regular vehicles, elevators or some doorways. Claws add 2D6 S.D.C. damage to (supernatural) strength; bites inflict 3D6 S.D.C.; can leap 30 feet from a standing position and 60 feet with a running start.', 'The book prints the Speed-is-increased-by-1D6x10 line twice in this entry (once as running speed, once repeated); treated as a single Spd bonus, not a duplicate/extra one.', 'import', 'Nightbane RPG p.97', 'nightbane'),
  ('Feline: Cat Claws', 'Feline', 70, 80, 'Cat Claws', 'effect', NULL, NULL, NULL, NULL, NULL, NULL, 'Gains retractable claws (add +5% to Climbing rolls) and inflicts 2D4 S.D.C. in addition to normal P.S. damage. The book gives no Horror Factor for this entry.', 'No Horror Factor is printed for this entry.', 'import', 'Nightbane RPG p.97', 'nightbane'),
  ('Feline: Cat''s Head', 'Feline', 81, 90, 'Cat''s Head', 'effect', NULL, NULL, '{"combat": {"initiative": 1}}', '1d4', NULL, NULL, 'Normal humanoid body but a fully feline head. Nightvision 600 feet. Bite inflicts 4D6 S.D.C.', 'Cache prints "600 feet/1 83 m. m." (duplicated "m."); read as 600 ft / 183 m.', 'import', 'Nightbane RPG p.97', 'nightbane'),
  ('Feline: Feline Features', 'Feline', 91, 100, 'Feline Features', 'effect', NULL, NULL, '{"combat": {"perception": 1}}', NULL, NULL, NULL, 'Lesser form of Cat''s Head: sharp teeth (bite inflicts 1D8 S.D.C. damage), cat''s eyes with vertical slits (nightvision 500 feet), and furry, pointed ears near the top of the head. The book gives no Horror Factor for this entry.', 'Cache reads the bite die as "IDS"; resolved as 1D8 per the substitution cipher (S=8 here) and confirmed against the morphus-map render of printed 98.', 'import', 'Nightbane RPG p.98', 'nightbane'),
  ('Insectoid: Insectoid Table', 'Insectoid', 0, 0, 'Insectoid Table', 'intro', NULL, NULL, NULL, NULL, NULL, NULL, 'Roll or select. Players select the insect species; Game Masters may modify the bonuses to better represent the species picked. All insect Nightbane instinctively know how to swim at a base proficiency of 50%, have acrobatics at 50% and climb at 60% (unless stated otherwise), as well as +1 to roll with fall or impact.', NULL, 'import', 'Nightbane RPG p.98', 'nightbane'),
  ('Insectoid: Giant Insect', 'Insectoid', 1, 15, 'Giant Insect', 'effect', NULL, NULL, '{"attributes": {"PS": 10, "PP": 3, "PE": 4}, "combat": {"initiative": 3, "perception": 3}}', '1d6', NULL, '["hard-bodied", "soft-bodied", "run", "fly"]', 'Giant insect at least six feet long (spiders/scorpions are not insects; ants, bees, wasps, flies, dragonflies, mosquitoes, beetles, praying mantis, butterflies and moths are typical). Either +1D4x10 to running speed OR a flying speed of 2D4x10. S.D.C. is +4D6x10 for hard-body insects (ants, beetles) or +2D6x10 for soft-body insects (flies, butterflies). Claws add 1D6 S.D.C. to hand to hand damage; pincers 2D6; mandible bite is 2D4 S.D.C. (small), 2D6 (medium) or 4D6 (large, e.g. ants/beetles). Wasp/bee-type stingers inflict 2D6 stab damage plus 1D6 poison damage; victims are -2 initiative and -1 strike/parry/dodge unless they save vs non-lethal poison; the stinger does not fall off and can sting repeatedly. Cannot use tools or weapons or perform complex skills requiring hands/dexterity (-40%).', NULL, 'import', 'Nightbane RPG p.98', 'nightbane'),
  ('Insectoid: Were-Insect', 'Insectoid', 16, 35, 'Were-Insect', 'effect', NULL, NULL, '{"attributes": {"PS": 6, "PP": 3, "PE": 3}, "combat": {"initiative": 2, "perception": 3, "attacks": 1}}', '1d6', NULL, '["hard-bodied", "soft-bodied", "run", "fly"]', 'Bipedal combination of human and insect: two pairs of clawed, spindly arms/hands/legs, vaguely humanoid shape, insectoid head with antennae, pincer-like mandibles and multi-faceted eyes. Either +5D6 to running speed OR a flying speed of 2D4x10. S.D.C. is +3D6x10 for hard-body insects or +2D4x10 for soft-body insects. Claws add 1D6 S.D.C. to hand to hand damage; the extra pair of arms grants the extra attack. Mouth mandibles inflict 3D6 points of damage.', NULL, 'import', 'Nightbane RPG p.98-99', 'nightbane'),
  ('Insectoid: Humanoid-Insectoid', 'Insectoid', 36, 55, 'Humanoid-Insectoid', 'effect', NULL, NULL, '{"attributes": {"PS": 4, "PP": 2, "PE": 2}, "combat": {"initiative": 1, "perception": 2, "attacks": 1}}', '1d4', NULL, '["hard-bodied", "soft-bodied", "run", "fly"]', 'Basically human-like, with an extra pair of arms and a number of insectoid characteristics; human head except for large, round, multi-faceted eyes and antennae; skin covered by a chitinous exoskeleton. May have insect wings, but no other unusual limbs. Either +3D6 to running speed OR a flying speed of 1D4x10. Exoskeleton S.D.C. is +2D6x10 for hard-body insects or +1D6x10 for soft-body insects. Claws add 1D6 S.D.C. to hand to hand damage; the pair of extra arms grants the extra attack.', NULL, 'import', 'Nightbane RPG p.99', 'nightbane'),
  ('Insectoid: Insect Wings', 'Insectoid', 56, 70, 'Insect Wings', 'effect', NULL, NULL, '{"pools": {"sdc": "3d6"}}', '1', NULL, NULL, 'Otherwise normal body except for insect wings protruding from the back. Can fly with a speed of 1D4x10+20, and +1 to dodge when flying.', NULL, 'import', 'Nightbane RPG p.99', 'nightbane'),
  ('Insectoid: Insect Head', 'Insectoid', 71, 80, 'Insect Head', 'effect', NULL, NULL, '{"combat": {"initiative": 2, "perception": 3}, "pools": {"sdc": "2d6"}}', '1d4', NULL, NULL, 'Ordinary-looking human except for the full insect head. Mandibles bite for 4D6 S.D.C. damage.', NULL, 'import', 'Nightbane RPG p.99', 'nightbane'),
  ('Insectoid: Insect Eyes', 'Insectoid', 81, 90, 'Insect Eyes', 'effect', NULL, NULL, '{"combat": {"perception": 2}}', NULL, NULL, NULL, 'Multi-faceted eyes: polarized vision (works like sunglasses to reduce glare), can see in the ultraviolet and infrared spectrum of light. Unless the eyes are covered with sunglasses or mirror goggles, add +2 to Horror Factor (conditional, not counted in the horror_factor field).', 'Horror Factor +2 here is conditional ("unless the eyes are covered"), so it is left out of horror_factor and described instead.', 'import', 'Nightbane RPG p.99', 'nightbane');
INSERT INTO morphus_characteristics
  (key, table_name, roll_low, roll_high, name, kind, routes, route_rule, bonuses, horror_factor, horror_factor_set, sub_choices, description, note, source, source_book, system)
VALUES
  ('Insectoid: Insectoid Centauroid', 'Insectoid', 91, 100, 'Insectoid Centauroid', 'effect', NULL, NULL, '{"attributes": {"PS": 6, "PP": 2, "PE": 2, "Spd": "5d6"}, "combat": {"initiative": 1, "perception": 3}}', '1d6', NULL, '["with wings", "without wings"]', 'Upper body of an insect-like humanoid with insect mandibles, eyes and antennae; lower body of a six-legged giant insect that may also have wings. If it has wings, also gains a flying speed of 1D6x10. Clawed hands add 1D6 S.D.C. to hand to hand damage; mouth mandibles inflict 3D6 points of damage.', NULL, 'import', 'Nightbane RPG p.99', 'nightbane'),
  ('Reptilian: Reptilian Table', 'Reptilian', 0, 0, 'Reptilian Table', 'intro', NULL, NULL, NULL, NULL, NULL, NULL, 'Roll or select. All reptilians instinctively know how to swim at a base proficiency of 45% and climb at 35%.', NULL, 'import', 'Nightbane RPG p.99', 'nightbane'),
  ('Reptilian: Giant Reptile', 'Reptilian', 1, 20, 'Giant Reptile', 'effect', NULL, NULL, '{"attributes": {"PS": 3, "PE": 4, "PP": 3, "Spd": "4d6"}, "pools": {"sdc": "3d6x10"}}', '3', NULL, NULL, 'Giant lizard, typically over seven feet tall counting the tail (length = the character''s Facade height + 1D6 feet); may be mistaken for a Komodo dragon, crocodile or similar large natural reptile. Can move in great bursts of speed, but maximum speed cannot be maintained for more than 3D4 minutes. Bite inflicts 4D6 S.D.C. damage; claws 2D6.', NULL, 'import', 'Nightbane RPG p.99', 'nightbane'),
  ('Reptilian: Were-Reptile', 'Reptilian', 21, 40, 'Were-Reptile', 'effect', NULL, NULL, '{"attributes": {"PS": 5, "PE": 3, "PP": 2, "Spd": "2d6"}, "pools": {"sdc": "2d6x10"}}', '1d4+1', NULL, NULL, 'Bipedal mixture of man and reptile, with reptilian features predominating; head fully animal-like, arms and legs underdeveloped but incredibly strong and tipped by razor sharp claws. Clawed hands and feet add 2D6 S.D.C. to hand to hand damage and +10% to climbing skill. Bite inflicts 3D6 damage.', NULL, 'import', 'Nightbane RPG p.99', 'nightbane'),
  ('Reptilian: Humanoid-Reptilian', 'Reptilian', 41, 60, 'Humanoid-Reptilian', 'effect', NULL, NULL, '{"attributes": {"PS": 3, "PE": 2, "PP": 2, "Spd": "1d6"}, "pools": {"sdc": "2d4x10"}}', '1d4', NULL, NULL, 'Human-shaped, scale-covered creature able to pass for human if covered by heavy clothing (trench coat or cape) or seen from a distance or in shadow. Clawed hands and feet add 2D4 S.D.C. to hand to hand damage and +5% to climbing skill. Bite inflicts 2D6 damage.', NULL, 'import', 'Nightbane RPG p.99', 'nightbane'),
  ('Reptilian: Reptile''s Head', 'Reptilian', 61, 80, 'Reptile''s Head', 'effect', NULL, NULL, '{"pools": {"sdc": "2d6"}}', '1d4', NULL, NULL, 'Human body except for the fully reptilian head. Bite inflicts 4D6 damage.', NULL, 'import', 'Nightbane RPG p.99', 'nightbane'),
  ('Reptilian: Reptilian Centauroid', 'Reptilian', 81, 100, 'Reptilian Centauroid', 'effect', NULL, NULL, '{"attributes": {"PS": 5, "PE": 3, "PP": 3, "Spd": "4d6"}, "pools": {"sdc": "3d6x10"}}', '1d6', NULL, NULL, 'Huge creature with the lower body of a reptile (four legs and a tail) and the upper body a scale-covered humanoid torso with a human-like head; hard-pressed to fit into a vehicle or small room. Clawed hands and feet add 2D6 S.D.C. to hand to hand damage; bite inflicts 3D6 damage.', NULL, 'import', 'Nightbane RPG p.99', 'nightbane'),
  ('Rodent: Rodent Table', 'Rodent', 0, 0, 'Rodent Table', 'intro', NULL, NULL, NULL, NULL, NULL, NULL, 'Roll or select. Includes all types of rats (most common), mice, shrews, squirrels, chipmunks, rabbits, moles and similar animals, whether or not true rodents zoologically. No table-wide innate skill is granted in the preamble.', NULL, 'import', 'Nightbane RPG p.100', 'nightbane'),
  ('Rodent: Full Rodent', 'Rodent', 1, 20, 'Full Rodent', 'effect', NULL, NULL, '{"attributes": {"PS": 4, "PP": 4, "PE": 5, "Spd": "4d6"}, "combat": {"initiative": 1, "perception": 3}, "pools": {"sdc": "2d6x10"}}', '1d4', NULL, NULL, 'Shape of a giant rat, roughly the size of a small bear or mountain lion. +10% to climb (if no climb skill is known, instinctively climbs at a base 30%); can leap 10 feet high or lengthwise. Nightvision 1000 feet. Can use tools/weapons but very poorly (-6 to strike or -30% on skill performance); cannot punch or kick effectively, but can parry and slash with claws: 1D6 damage from a claw strike, 3D6 S.D.C. from a bite, and a body slam or jump kick does 2D6 damage.', NULL, 'import', 'Nightbane RPG p.100', 'nightbane'),
  ('Rodent: Were-Rat', 'Rodent', 21, 45, 'Were-Rat', 'effect', NULL, NULL, '{"attributes": {"PS": 3, "PP": 3, "PE": 4, "Spd": "3d6"}, "combat": {"initiative": 1, "perception": 2}, "pools": {"sdc": "1d6x10"}}', '1d6', NULL, NULL, 'Vaguely humanoid rat-creature, able to stand on two feet, with a long tail, fairly short arms, clawed hands and a full rat''s head; almost impossible to disguise even with heavy clothing. Bite inflicts 3D6 S.D.C.; claws add 1D6 S.D.C. to hand to hand damage. Nightvision 1000 feet.', NULL, 'import', 'Nightbane RPG p.100', 'nightbane'),
  ('Rodent: Humanoid Rodent', 'Rodent', 46, 70, 'Humanoid Rodent', 'effect', NULL, NULL, '{"attributes": {"PS": 2, "PP": 2, "PE": 2, "Spd": "2d6"}, "combat": {"perception": 1}, "pools": {"sdc": "4d6"}}', '2', NULL, NULL, 'Fur-covered humanoid; head is mostly human-like but projects forward more than normal, giving "weasel" or "rat" features; no tail, and sparse fur near the face/hands allows the character to pass for a normal human in bad light. Bite inflicts 2D6 S.D.C.; claws add 1D4 S.D.C. to hand to hand damage. Nightvision 500 feet.', NULL, 'import', 'Nightbane RPG p.100', 'nightbane'),
  ('Rodent: Rodent Head', 'Rodent', 71, 90, 'Rodent Head', 'effect', NULL, NULL, '{"combat": {"initiative": 1, "perception": 2}}', '1d4', NULL, NULL, 'Normal human body, but the head is that of a giant rat or other rodent. Bite inflicts 2D6 S.D.C. Nightvision 1000 feet.', NULL, 'import', 'Nightbane RPG p.100', 'nightbane'),
  ('Rodent: Rodent Centauroid', 'Rodent', 91, 100, 'Rodent Centauroid', 'effect', NULL, NULL, '{"attributes": {"PS": 4, "PE": 5, "PP": 2, "Spd": "4d6"}, "combat": {"initiative": 1, "perception": 3}, "pools": {"sdc": "3d6x10"}}', '1d4', NULL, NULL, 'Lower body of a giant rat, upper body a humanoid. Bite inflicts 3D6 S.D.C.; claws add 1D4 S.D.C. to hand to hand damage. Nightvision 500 feet.', NULL, 'import', 'Nightbane RPG p.100', 'nightbane'),
  ('Snake: Snake Table', 'Snake', 0, 0, 'Snake Table', 'intro', NULL, NULL, NULL, NULL, NULL, NULL, 'Roll percentile dice or select. All snake Nightbane instinctively know how to swim at a base proficiency of 55% and climb at 40% (unless stated otherwise).', NULL, 'import', 'Nightbane RPG p.100', 'nightbane'),
  ('Snake: Full Snake Form', 'Snake', 1, 15, 'Full Snake Form', 'effect', NULL, NULL, '{"attributes": {"PS": 6, "PE": 3, "PP": 2}, "pools": {"sdc": "2d6x10"}}', '5', NULL, '["poisonous", "constrictor", "neither"]', 'Shape of a giant snake, at least six feet long (length = the character''s Facade length + 1D6 feet). Has a base Climbing skill of 60%, or +20% to the character''s current climbing skill, whichever is greater (Morphus form only). If the Morphus is a poisonous serpent (asp, cobra, rattlesnake, viper, etc.): bite inflicts 2D6 S.D.C. plus venom does 6D6 damage (3D6 if a successful save vs lethal poison), and adds another +1 to Horror Factor. If a constrictor: has all the base abilities of the wrestling skill, can jab with its head or coil from its body to do the equivalent of punch damage; crushing/constricting attacks do double the character''s normal punch damage plus P.S. bonuses, and each act of constriction does damage and counts as one melee attack.', NULL, 'import', 'Nightbane RPG p.100', 'nightbane'),
  ('Snake: Limbed Snake', 'Snake', 16, 30, 'Limbed Snake', 'effect', NULL, NULL, '{"attributes": {"PS": 4, "PE": 2, "PP": 2}, "combat": {"attacks": 1}, "pools": {"sdc": "2d4x10"}}', '1d6', NULL, '["poisonous", "constrictor", "neither"]', 'A pair of scaly human-like arms, hands and legs stemming from a long snake-like body; an overlong "neck" and a snake''s head; the "torso" bends and twists with the full flexibility of a serpent, and all limbs are double jointed and ambidextrous. Add +15% to the Climbing skill if the character possesses it, otherwise the base ability applies. If poisonous: bite inflicts 2D6 S.D.C. plus venom does 4D6 damage (2D6 if a successful save vs lethal poison). If a constrictor: same wrestling/jab/crush rules as Full Snake Form.', NULL, 'import', 'Nightbane RPG p.100', 'nightbane'),
  ('Snake: Humanoid Snake', 'Snake', 31, 50, 'Humanoid Snake', 'effect', NULL, NULL, '{"attributes": {"PS": 3, "PE": 2, "PP": 1}, "combat": {"attacks": 1}, "pools": {"sdc": "1d6x10"}}', '1d4+1', NULL, '["poisonous", "non-poisonous"]', 'Basic build and shape of a human being, but skin is covered by colorful scales, head and neck are those of a snake, and it has a long prehensile tail. Sharp fangs plus sharp claws on hands and feet add 1D6 S.D.C. damage to punches/claw strikes and kicks. Bite inflicts 2D6 S.D.C., and if a poisonous variety injects venom doing 3D6 damage (1D6 on a successful save vs lethal poison). The prehensile tail can hit, hold and carry objects or aid climbing (add +10% to the climbing skill).', NULL, 'import', 'Nightbane RPG p.100', 'nightbane'),
  ('Snake: Scaly Skin', 'Snake', 51, 70, 'Scaly Skin', 'effect', NULL, NULL, '{"pools": {"sdc": "1d6x10"}}', '1d4', NULL, NULL, 'A normal human body and features except for scale-covered skin and eyes that are snake-like in appearance.', NULL, 'import', 'Nightbane RPG p.101', 'nightbane'),
  ('Snake: Half-Man, Half-Snake', 'Snake', 71, 85, 'Half-Man, Half-Snake', 'effect', NULL, NULL, '{"attributes": {"PS": 4, "PE": 2, "PP": 3}, "combat": {"attacks": 1}, "pools": {"sdc": "1d6x10+10"}}', '1d6', NULL, '["poisonous", "constrictor", "neither"]', 'Scale-covered human torso with arms and hands, a human head, and a long snake-like body and tail; has no legs and must crawl or climb using the lower body; the upper torso bends and twists with the full flexibility of a serpent, and all limbs are double jointed and ambidextrous. Add +20% to the climbing skill if the character possesses it. If poisonous: bite inflicts 2D6 S.D.C. plus venom does 4D6 damage (2D6 if a successful save vs lethal poison). If a constrictor: same wrestling/jab/crush rules as Full Snake Form.', 'The printed "Add 1D6 to Horror Factor" sentence sits directly after the poisonous-serpent clause and before the constrictor clause, with no other Horror Factor given for this entry. Treated here as the entry''s base Horror Factor (as in Snake''s Head, where a trailing HF line is unconditional), but the placement makes it ambiguous whether it was meant to apply only when poisonous; flagging for reconcile.', 'import', 'Nightbane RPG p.101', 'nightbane'),
  ('Snake: Snake''s Head', 'Snake', 86, 100, 'Snake''s Head', 'effect', NULL, NULL, '{"pools": {"sdc": "2d6"}}', '1d4', NULL, '["poisonous", "non-poisonous"]', 'Normal human body topped by a giant snake''s head. Bite inflicts 3D6 S.D.C., plus if poisonous an additional 3D6 damage (1D6 if a successful save vs lethal poison).', NULL, 'import', 'Nightbane RPG p.101', 'nightbane'),
  ('Alien Shape: Alien Shape Table', 'Alien Shape', 0, 0, 'Alien Shape Table', 'intro', NULL, NULL, NULL, NULL, NULL, NULL, 'Roll or select. Covers unusual shapes and forms that manifest in some Nightbane; players are invited to decide what the alien form reflects about the character''s soul or subconscious. No table-wide numeric grant is printed in the preamble.', NULL, 'import', 'Nightbane RPG p.103', 'nightbane'),
  ('Alien Shape: Plasmoid', 'Alien Shape', 1, 12, 'Plasmoid', 'effect', NULL, NULL, '{"pools": {"sdc": "4d6"}}', '1d6', NULL, NULL, 'Body has a semi-liquid, jelly-like blood consistency. Basic shape stays a bipedal humanoid (can keep the exact outline of the Facade) but can be stretched, spread or puddled at will. Can squeeze through narrow openings (a couple of inches), slip out of restraints, and conceal itself as a glob or goo. All physical attacks against the character do half damage.', NULL, 'import', 'Nightbane RPG p.103', 'nightbane'),
  ('Alien Shape: Bark-like Skin', 'Alien Shape', 13, 24, 'Bark-like Skin', 'effect', NULL, NULL, '{"pools": {"sdc": "1d4x10"}}', '1d4', NULL, NULL, 'Looks like a combination of tree and human: bark instead of skin, often leaves or vines instead of hair.', NULL, 'import', 'Nightbane RPG p.103', 'nightbane'),
  ('Alien Shape: Bony Exoskeleton', 'Alien Shape', 25, 37, 'Bony Exoskeleton', 'effect', NULL, NULL, '{"pools": {"sdc": "1d6x10"}}', '1d4', NULL, NULL, 'Covered with bone-like plates or large scales, often with horn-like protrusions and short spikes. Adds 1D6 S.D.C. to all hand to hand damage.', NULL, 'import', 'Nightbane RPG p.103', 'nightbane'),
  ('Alien Shape: Thorns', 'Alien Shape', 38, 45, 'Thorns', 'effect', NULL, NULL, '{"pools": {"sdc": "4d6"}}', '1d4', NULL, NULL, 'Thorns protrude from the body; may look like natural growths or stigmata-like, appearing to painfully pierce the skin.', NULL, 'import', 'Nightbane RPG p.103', 'nightbane'),
  ('Alien Shape: Crystalline', 'Alien Shape', 46, 54, 'Crystalline', 'effect', NULL, NULL, '{"pools": {"sdc": "2d4x10"}}', '2', NULL, NULL, 'Looks predominately human but has quartz- or diamond-like crystals growing from the skin along fingers, hand bones, arms, spine, elbows, shoulders and knees; the hair may be a cap or crown of crystal. Heat and fire do half damage. Can parry bladed weapons and fiery torches bare-handed. Fingernails are jagged crystal that slash for 1D6 S.D.C. plus punch damage, and the crystal-encrusted hands act like brass knuckles, adding 1D6 S.D.C. to punch damage. In bright light the character glitters like a gem and may (1-60% chance) blind onlookers with the reflected light.', NULL, 'import', 'Nightbane RPG p.103', 'nightbane'),
  ('Alien Shape: Living Tattoos', 'Alien Shape', 55, 66, 'Living Tattoos', 'effect', NULL, NULL, NULL, NULL, NULL, '["tattoos reflect the character''s current emotional state (uncontrolled)", "tattoos are controlled directly by the character"]', 'Skin is covered with tattoos that change and move (50-50 chance which mode, or select one). Adds 1D6 to Horror Factor whenever someone notices the moving tattoos.', 'The +1D6 Horror Factor is conditional (only when the moving tattoos are noticed), so it is not in horror_factor.', 'import', 'Nightbane RPG p.103', 'nightbane'),
  ('Alien Shape: Unusual Skin Color', 'Alien Shape', 67, 77, 'Unusual Skin Color', 'effect', NULL, NULL, NULL, '1', NULL, '["yellow", "red", "green", "blue", "purple/violet", "copper", "gold", "metallic grey", "silver", "pitch black", "stark white"]', 'Skin has an inhuman, too-intense hue, not body paint or dye. Roll or pick one color.', NULL, 'import', 'Nightbane RPG p.103', 'nightbane'),
  ('Alien Shape: Hulking Monster', 'Alien Shape', 78, 85, 'Hulking Monster', 'effect', NULL, NULL, '{"attributes": {"PS": "1d4"}, "pools": {"sdc": "1d6x10"}}', '1d4', NULL, NULL, 'Huge, hulking brute: large barrel chest, hunched back, long gorilla-like arms, and a comparatively tiny (human-sized) head that may be human, alien, animal or monstrous. Stands 1D6+6 feet tall (with a hunched back) and weighs 80 lb (36.3 kg) per foot (0.3 m) of height. Add +2 to roll with fall or impact. Reduce the character''s Speed by 10%.', NULL, 'import', 'Nightbane RPG p.103', 'nightbane'),
  ('Alien Shape: Mouth-Covered Body', 'Alien Shape', 86, 95, 'Mouth-Covered Body', 'effect', NULL, NULL, NULL, '1d4+2', NULL, NULL, 'Body is covered by 2D6x10 tiny mouths that can gesture, stick out tongues, whistle, hoot, growl or scream, but cannot speak. Adds 3 to Horror Factor when all the mouths are screaming/screeching at once. The character can grapple a foe and let the tiny mouths bite (1D4 damage per mouth; typically 1D6 mouths bite at once).', 'The +3 Horror Factor ''when all of them are screaming'' is conditional and is not in horror_factor (only the flat +1D4+2 is).', 'import', 'Nightbane RPG p.103-104', 'nightbane'),
  ('Alien Shape: Combination of Two', 'Alien Shape', 96, 100, 'Combination of Two', 'combination', '[{"table": "Alien Shape", "count": 2}]', 'Roll twice more, ignoring and rerolling any result of 96 or higher, then combine the two results.', NULL, NULL, NULL, NULL, NULL, NULL, 'import', 'Nightbane RPG p.104', 'nightbane'),
  ('Unnatural Limbs: Unnatural Limbs Table', 'Unnatural Limbs', 0, 0, 'Unnatural Limbs Table', 'intro', NULL, NULL, NULL, NULL, NULL, NULL, 'No preamble or table-wide grant is printed; entries begin immediately after the table header.', NULL, 'import', 'Nightbane RPG p.104', 'nightbane'),
  ('Unnatural Limbs: Prehensile Tail', 'Unnatural Limbs', 1, 10, 'Prehensile Tail', 'effect', NULL, NULL, '{"combat": {"attacks": 1}}', '1', NULL, NULL, 'A strong prehensile tail usable to grasp, carry things, or help climb; can support the character''s full body weight when suspended, but can only carry about one-third of the character''s body weight (typically about 60 lbs/27.2 kg). Adds +20% to climb and balance when the tail is used.', NULL, 'import', 'Nightbane RPG p.104', 'nightbane'),
  ('Unnatural Limbs: Spiked Prehensile Tail', 'Unnatural Limbs', 11, 20, 'Spiked Prehensile Tail', 'effect', NULL, NULL, '{"combat": {"attacks": 1}}', '1', NULL, NULL, 'Same as Prehensile Tail (climb/balance +20% when used, one extra melee action, carries about one-third body weight) except the tail ends in a spike, blade, stinger or club with 2D4 small spikes. Tail strikes inflict 2D6 damage.', '''Same as above'' in the book; bonuses/H.F. carried over from Prehensile Tail are assumed to apply here too.', 'import', 'Nightbane RPG p.104', 'nightbane'),
  ('Unnatural Limbs: Tentacles', 'Unnatural Limbs', 21, 30, 'Tentacles', 'effect', NULL, NULL, '{"combat": {"attacks": 1}}', '1d4', NULL, NULL, 'Two tentacles in addition to the arms; hard to conceal (needs at least a trench coat, cape or cloak). Can grab and carry objects but cannot use firearms or other tools requiring fingers. A pair of tentacle strikes adds 1D6 S.D.C. to normal hand to hand damage.', NULL, 'import', 'Nightbane RPG p.104', 'nightbane'),
  ('Unnatural Limbs: Long, Sensitive Fingers', 'Unnatural Limbs', 31, 40, 'Long, Sensitive Fingers', 'effect', NULL, NULL, NULL, NULL, NULL, NULL, 'Fingers are three times longer than normal, delicate and sensitive. +5% to each of: Medical (all), demolitions (both), electronics (all), computers (all), pick locks, pick pockets, and climbing.', 'No Horror Factor bonus is printed for this entry.', 'import', 'Nightbane RPG p.104', 'nightbane'),
  ('Unnatural Limbs: 2D4 Pairs of Tiny Arms and Hands', 'Unnatural Limbs', 41, 50, '2D4 Pairs of Tiny Arms and Hands', 'effect', NULL, NULL, NULL, '1d4', NULL, NULL, '2D4 pairs of tiny arms, about one-third the size of a normal arm, usually along the forearm(s) or clustered at the shoulder(s). Each has P.S. 1D6 and inflicts 1 point of damage in combat (only if a foe gets close enough). Can grab/carry small or light objects, or wield razor blades, small knives, or ice picks (1D4 damage each).', NULL, 'import', 'Nightbane RPG p.104', 'nightbane'),
  ('Unnatural Limbs: Four Arms', 'Unnatural Limbs', 51, 65, 'Four Arms', 'effect', NULL, NULL, '{"combat": {"attacks": 1}}', '1d4', NULL, NULL, 'An extra pair of arms and hands; all arms are ambidextrous and double jointed.', NULL, 'import', 'Nightbane RPG p.104', 'nightbane'),
  ('Unnatural Limbs: Pseudopods', 'Unnatural Limbs', 66, 80, 'Pseudopods', 'effect', NULL, NULL, NULL, NULL, NULL, NULL, 'At will, extracts 1D4+1 tentacle-like limbs from the flesh (horrible to witness, as if breaking through the skin like a parasite). Treat as Tentacles (1D6 S.D.C. added to hand to hand damage per pair); adds one melee attack for each pair; each pseudopod has 22 S.D.C. Adds 1D4+2 to Horror Factor whenever the pseudopods are extended.', 'Both the extra-attack count and the +1D4+2 Horror Factor are conditional on how many pseudopods are extended, so neither is in bonuses/horror_factor.', 'import', 'Nightbane RPG p.104', 'nightbane'),
  ('Unnatural Limbs: Articulated Spikes', 'Unnatural Limbs', 81, 90, 'Articulated Spikes', 'effect', NULL, NULL, '{"combat": {"attacks": 1, "parry": 2}}', '1d4', NULL, NULL, 'Four insect-spine-like spikes, each about the size of a survival knife but able to extend to twice that length instantly; typically along the forearms (two per arm), or on the chest or sides of the body. Slim and chitinous, they move independently, rotate 360 degrees, and are used to parry hand to hand attacks and to stab/slash opponents within arm''s length; each spike inflicts 2D6 S.D.C. They cannot grab or manipulate objects.', NULL, 'import', 'Nightbane RPG p.104-105', 'nightbane');
INSERT INTO morphus_characteristics
  (key, table_name, roll_low, roll_high, name, kind, routes, route_rule, bonuses, horror_factor, horror_factor_set, sub_choices, description, note, source, source_book, system)
VALUES
  ('Unnatural Limbs: Antenna', 'Unnatural Limbs', 91, 100, 'Antenna', 'effect', NULL, NULL, NULL, '1', NULL, NULL, 'A pair of antennae on the head, each moving independently like an arm and able to dodge attacks aimed at them (+3 to dodge; each antenna has 15 S.D.C. and regenerates within 72 hours). Can resemble any insect or crustacean antennae; typically thin, whip-like, extending 1D4 feet (0.3-1.2 m). Lets the character move in total darkness; automatically senses air temperature/humidity changes and wind movement/direction; detects and identifies common odors (66%), tracks by smell (50%), and senses an approaching rainstorm (70%; arrives within 2D6x10 minutes).', 'The +3 dodge is described as being ''for the antennae'' (defending the antennae themselves), so it is treated as situational and left out of bonuses.', 'import', 'Nightbane RPG p.105', 'nightbane'),
  ('Biomechanical: Biomechanical Table', 'Biomechanical', 0, 0, 'Biomechanical Table', 'intro', NULL, NULL, NULL, NULL, NULL, NULL, 'Roll or select. Biomechanical Nightbane range from sword- or gauntlet-like limbs, to steam-powered/piston-driven limbs and riveted metal skin, to modern cyborg components; they are said to reflect the character''s fascination or fear toward machines/science. Table-wide grant: despite the artificial look, biomechanical characteristics are as much a living part of the Nightbane''s body as natural skin and bone - they have none of the limitations of true cybernetic prosthetics, and heal at the same rate as the rest of the Nightbane.', NULL, 'import', 'Nightbane RPG p.105', 'nightbane'),
  ('Biomechanical: Armorgraft', 'Biomechanical', 1, 10, 'Armorgraft', 'effect', NULL, NULL, '{"pools": {"sdc": "1d6x10"}}', '2', NULL, NULL, 'Pieces of archaic body armor (helmets, breastplates, gauntlets, chain mail, segmented mail) fused with the skin.', NULL, 'import', 'Nightbane RPG p.105', 'nightbane'),
  ('Biomechanical: Plastic', 'Biomechanical', 11, 20, 'Plastic', 'effect', NULL, NULL, '{"pools": {"sdc": "5d6"}}', '1', NULL, '["opaque plastic or rubber (any color/texture, player''s choice)", "transparent plastic (reveals internal organs)"]', 'Parts or all of the skin replaced with plastic or rubber; player picks color and texture. If the covering is transparent plastic revealing the internal organs, Horror Factor is 1D6 instead of the usual +1.', 'Horror Factor here is conditional on the texture choice: +1 normally, or 1D6 if transparent/organs visible. horror_factor holds the default (+1) case.', 'import', 'Nightbane RPG p.105', 'nightbane'),
  ('Biomechanical: Rocket Jets', 'Biomechanical', 21, 25, 'Rocket Jets', 'effect', NULL, NULL, '{"pools": {"sdc": "4d6"}}', '1', NULL, NULL, 'Metallic exhaust tubes and small jet engines grow from the back, providing limited flight: 80 mph (128 km), maximum altitude 5,000 feet (1524 m), and hover capability. The jets roar audibly, so prowl is impossible even while hovering.', NULL, 'import', 'Nightbane RPG p.105', 'nightbane'),
  ('Biomechanical: Metal Teeth and Talons', 'Biomechanical', 26, 30, 'Metal Teeth and Talons', 'effect', NULL, NULL, NULL, '2', NULL, NULL, 'Metal fangs and talons instead of normal teeth and fingernails (may be retractable). Metal teeth inflict 3D6 points of damage with a bite, and the claws add 1D6 S.D.C. to hand to hand damage.', NULL, 'import', 'Nightbane RPG p.105', 'nightbane'),
  ('Biomechanical: Metal Endoskeleton', 'Biomechanical', 31, 40, 'Metal Endoskeleton', 'effect', NULL, NULL, '{"attributes": {"PS": 2, "PE": 2}, "pools": {"hp": "1d6", "sdc": "2d4x10"}}', NULL, NULL, NULL, 'Metallic bones mixed with living flesh; there is always a place where metal seems to rip through the skin, usually on the hands, arms, neck, cheeks and legs.', 'No Horror Factor bonus is printed for this entry, unlike every other Biomechanical entry.', 'import', 'Nightbane RPG p.105', 'nightbane'),
  ('Biomechanical: Mechanical Limbs', 'Biomechanical', 41, 50, 'Mechanical Limbs', 'effect', NULL, NULL, '{"attributes": {"PS": 4}, "pools": {"sdc": "1d4x10"}}', '1d4', NULL, '["arms only (mechanical)", "arms and legs (both mechanical)"]', 'Arms and legs are obviously mechanical: piston-driven iron/bronze mechanisms, or microchip-covered/chrome-plated ''cyberpunk'' style. Don''t bleed when struck; instead oil/grease or wires and components show. If the legs are also mechanical, add +4D6 to Speed.', NULL, 'import', 'Nightbane RPG p.105', 'nightbane'),
  ('Biomechanical: Weapon Hand', 'Biomechanical', 51, 60, 'Weapon Hand', 'effect', NULL, NULL, NULL, '2', NULL, '["knife", "sword", "battle axe", "trident", "sickle", "etc. (player''s choice of weapon type)"]', 'One or both hands can metamorphose at will into a hand to hand weapon. The weapon does normal damage for its type plus P.S. damage bonuses, with no risk of it breaking. The character is +1 to strike and parry with the weapon limb.', 'The +1 strike/parry is specific to attacks made with the weapon limb, so it is left out of bonuses.', 'import', 'Nightbane RPG p.105', 'nightbane'),
  ('Biomechanical: Metal Exoskeleton', 'Biomechanical', 61, 70, 'Metal Exoskeleton', 'effect', NULL, NULL, '{"attributes": {"PS": 2, "PE": 1}, "pools": {"sdc": "3d6x10"}}', '1d4', NULL, NULL, 'Covered in mechanical armor, hard and bulky with rivets and seams, or smooth and chrome-like; Victorian-era Nightbane often had riveted iron instead of skin, while modern ones favor metallic bands/plates resembling robots or power armor.', NULL, 'import', 'Nightbane RPG p.105', 'nightbane'),
  ('Biomechanical: Metal Head & Camera Eyes', 'Biomechanical', 71, 80, 'Metal Head & Camera Eyes', 'effect', NULL, NULL, NULL, '1d4', NULL, NULL, 'Head looks like a robot or cyborg; camera lenses protrude from the eye sockets. Raises Nightvision range to 2000 feet (610 m); provides telescopic sight (like high-powered binoculars) and polarized filters. Eyes can also project moving pictures of anything the character remembers (silent, but otherwise picture-perfect, and may reflect the character''s own bias/emotion).', NULL, 'import', 'Nightbane RPG p.105', 'nightbane'),
  ('Biomechanical: Wheels or Treads', 'Biomechanical', 81, 90, 'Wheels or Treads', 'effect', NULL, NULL, '{"attributes": {"Spd": "2d4x10", "PS": 3, "PE": 2}, "pools": {"sdc": "3d6x10"}}', '1d4', NULL, '["motorcycle", "four-wheeled vehicle", "miniature tank (with treads)"]', 'Instead of legs, a two-wheeled (or similar) man-machine hybrid; upper body looks human or half-cyborg, lower body is a vehicle. May find it difficult to operate indoors or in confined spaces.', NULL, 'import', 'Nightbane RPG p.105', 'nightbane'),
  ('Biomechanical: Gun Limbs', 'Biomechanical', 91, 100, 'Gun Limbs', 'effect', NULL, NULL, NULL, '1d4', NULL, NULL, 'One or more guns built into the body, usually a barrel protruding from flesh and muscle. Normal gun stats; the biggest gun available is a rifle type doing 6D6 S.D.C. damage. Requires a permanent P.P.E. sacrifice equal to 1 P.P.E. per die of damage, plus 2 P.P.E. if the gun is automatic (can fire bursts). The character must find ammunition; up to 100 bullets can be stored in the body (loading them inflicts 1D6 S.D.C. to self per 10 bullets stored).', NULL, 'import', 'Nightbane RPG p.106', 'nightbane');
INSERT INTO data_script_runs (filename) VALUES ('zzzzzzzzzzzzz-nb-morphus-characteristics.sql');
