-- D5, step 1's data (apps/character-creator/docs/surveys/nightbane-core.md): the Nightbane
-- Morphus tables, printed 91-106. 173 rows - 154 entries and one intro per table for 19 tables.
--
-- One-off data script, run once per environment. NOT a migration. Needs migration 068.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/zzzzzzzzzzzzz-nb-morphus-characteristics.sql
--
-- Extracted in three slices off the cache, with renders wherever the digit cipher made a
-- number doubtful, and every row checked against the page by a separate reconcile pass,
-- which found four defects - three intro citations and a missed wings choice - fixed here.
--
-- WHAT IS IN `bonuses` AND WHAT IS NOT. Only numbers the book applies unconditionally. A
-- bonus that holds only in a situation ("+2 to dodge while flying"), a natural weapon's
-- damage dice, senses, size and restrictions are in `description`. A Horror Factor that
-- applies only "when noticed" or "while extended" is left out of `horror_factor` and
-- described (Living Tattoos, Mouth-Covered Body, Pseudopods, Insect Eyes); Plastic carries
-- its default +1 and describes the transparent 1D6.
--
-- CALLS THE READING MADE, each checked by the reconcile pass and recorded in the row's note:
-- * Nightbane Characteristics 81-00 "ignore any result of 61% or higher" also shuts out
--   61-80 Unnatural Limbs from a multi-roll. Probably an erratum; stored as printed.
-- * Animal Form 01-07 Bear and 08-14 Amphibian route to tables the book never prints.
--   Nate (D5): a reroll in random mode, not offered in pick mode.
-- * Snake, Half-Man Half-Snake: its "Add 1D6 to Horror Factor" follows the poisonous
--   clause, where its twin Limbed Snake prints it before; read as unconditional.
-- * Feline Centauroid prints its +1D6x10 speed twice; one bonus.
-- * Spiked Prehensile Tail is "same as above": it carries Prehensile Tail's bonuses.
-- * Stigmata Nails, Metal Endoskeleton, Cat Claws, Feline Features and Winged Human print no
--   Horror Factor; none is invented.
--
-- An intro row is named by its printed heading ("Appearance Table") at band 0/0.






-- Read the result back. This batch asserts its OWN rows and nothing else.
SELECT 'all 173 Morphus rows are in, as nightbane' AS assertion, count(*) AS got, 173 AS want
  FROM morphus_characteristics WHERE system = 'nightbane' AND source_book LIKE 'Nightbane RPG p.%';

SELECT 'one intro per table, 19 tables' AS assertion, count(DISTINCT table_name) AS got, 19 AS want
  FROM morphus_characteristics WHERE system = 'nightbane' AND kind = 'intro';

SELECT '154 entries: 118 effect, 25 route, 11 combination' AS assertion, count(*) AS got, 154 AS want
  FROM morphus_characteristics WHERE system = 'nightbane'
   AND ((kind = 'effect') OR (kind = 'route') OR (kind = 'combination'));

SELECT 'every table covers 1-100 exactly' AS assertion, count(*) AS got, 0 AS want
  FROM (SELECT table_name, sum(roll_high - roll_low + 1) AS span, min(roll_low) AS lo, max(roll_high) AS hi
          FROM morphus_characteristics WHERE system = 'nightbane' AND kind <> 'intro'
         GROUP BY table_name)
 WHERE span <> 100 OR lo <> 1 OR hi <> 100;

